head.b:skin:
/* APK KIE - Blogger theme skin */
body{margin:0;background:#f4f6fb;color:#18233d;font-family:Arial,Helvetica,sans-serif}
a{color:inherit;text-decoration:none}

body.script:
(function(){
  'use strict';
  // IMPORTANT: Replace this with your deployed FastAPI backend URL (no trailing slash).
  const API_BASE = 'https://YOUR-BACKEND-DOMAIN';
  const form = document.getElementById('ak-form');
  const configWarning = document.getElementById('ak-config-warning');
  const tabs = Array.from(document.querySelectorAll('.ak-tab'));
  const advanced = Array.from(document.querySelectorAll('.ak-advanced'));
  const professional = Array.from(document.querySelectorAll('.ak-pro'));
  const modeInput = document.getElementById('ak-mode');
  const buildButton = document.getElementById('ak-build-btn');
  const statusBox = document.getElementById('ak-status-box');
  let activeBuildId = null;
  let pollTimer = null;
  const apiReady = /^https:\/\//i.test(API_BASE) && !API_BASE.includes('YOUR-BACKEND-DOMAIN');
  if(!apiReady) configWarning.classList.add('show');
  document.getElementById('ak-year').textContent = new Date().getFullYear();

  function setMode(mode){
    modeInput.value = mode;
    tabs.forEach(t => t.classList.toggle('active', t.dataset.mode === mode));
    advanced.forEach(el => el.classList.toggle('ak-hidden', mode === 'quick'));
    professional.forEach(el => el.classList.toggle('ak-hidden', mode !== 'pro'));
    document.getElementById('ak-output').value = 'apk';
  }
  tabs.forEach(t => t.addEventListener('click', () => setMode(t.dataset.mode)));
  document.getElementById('ak-name').addEventListener('input', e => { document.getElementById('ak-preview-name').textContent = e.target.value || 'Your App Name'; });
  document.getElementById('ak-url').addEventListener('input', e => { try{document.getElementById('ak-preview-url').textContent = new URL(e.target.value).hostname;}catch(_){document.getElementById('ak-preview-url').textContent='yourwebsite.com';} });
  document.getElementById('ak-icon').addEventListener('change', e => {
    const file = e.target.files && e.target.files[0]; if(!file) return;
    if(!file.type.startsWith('image/')) { alert('Please select an image file.'); e.target.value=''; return; }
    const reader = new FileReader(); reader.onload = () => { const img = document.createElement('img'); img.src = reader.result; const box = document.getElementById('ak-icon-preview'); box.textContent=''; box.appendChild(img); const prev = document.getElementById('ak-preview-icon'); prev.textContent=''; const pimg = document.createElement('img'); pimg.src=reader.result; pimg.style.cssText='width:100%;height:100%;object-fit:cover;border-radius:10px'; prev.appendChild(pimg); }; reader.readAsDataURL(file);
  });
  function showStatus(title,message,progress,error){
    statusBox.classList.add('show');
    document.getElementById('ak-status-title').textContent=title;
    document.getElementById('ak-status-message').textContent=message || '';
    document.getElementById('ak-status-percent').textContent=(progress||0)+'%';
    document.getElementById('ak-progress-bar').style.width=(progress||0)+'%';
    document.getElementById('ak-status-title').classList.toggle('ak-error',!!error);
  }
  async function parseResponse(response){ let data={}; try{data=await response.json();}catch(_){ } if(!response.ok) throw new Error(data.error?.message || data.detail || 'Request failed ('+response.status+').'); return data; }
  async function pollBuild(id){
    try{
      const response=await fetch(API_BASE+'/api/builds/'+encodeURIComponent(id));
      const data=await parseResponse(response);
      showStatus(data.status==='completed'?'Build complete':data.status==='failed'?'Build failed':'Building your app...',data.message,data.progress,data.status==='failed');
      if(data.status==='completed'){
        clearInterval(pollTimer); buildButton.disabled=false; buildButton.textContent='Generate Android App →';
        const link=document.createElement('a'); link.className='ak-download'; link.href=API_BASE+'/api/builds/'+encodeURIComponent(id)+'/download'; link.textContent='↓ Download '+(data.build_type||'APK').toUpperCase(); link.setAttribute('download','');
        const area=document.getElementById('ak-download-area'); area.replaceChildren(link); loadHistory();
      } else if(data.status==='failed') { clearInterval(pollTimer); buildButton.disabled=false; buildButton.textContent='Try Again'; loadHistory(); }
    }catch(error){ showStatus('Connection problem',error.message,0,true); clearInterval(pollTimer); buildButton.disabled=false; buildButton.textContent='Try Again'; }
  }
  form.addEventListener('submit', async e => {
    e.preventDefault();
    if(!apiReady){showStatus('Backend not configured','Set API_BASE in the Blogger theme to your deployed backend URL.',0,true);return;}
    if(!form.reportValidity()) return;
    const url=document.getElementById('ak-url').value.trim();
    if(!/^https:\/\//i.test(url)){showStatus('HTTPS required','Enter a website URL beginning with https://',0,true);return;}
    const icon=document.getElementById('ak-icon').files[0]; if(icon && icon.size>2*1024*1024){showStatus('Icon too large','Select an image smaller than 2 MB.',0,true);return;}
    const packageField=document.getElementById('ak-package');
    if(!packageField.value){const app=document.getElementById('ak-name').value.toLowerCase().replace(/[^a-z0-9]+/g,'.').replace(/^\.|\.$/g,'')||'myapp';packageField.value='com.apkie.'+app;}
    const data=new FormData(form);
    // Unchecked HTML checkboxes are absent; backend defaults them safely.
    buildButton.disabled=true;buildButton.textContent='Submitting build...';document.getElementById('ak-download-area').replaceChildren();
    showStatus('Submitting build','Connecting to APK KIE build server...',3,false);
    try{
      const response=await fetch(API_BASE+'/api/builds',{method:'POST',body:data});
      const result=await parseResponse(response); activeBuildId=result.build_id;
      showStatus('Build queued','Your Android project is being prepared.',5,false);
      if(pollTimer) clearInterval(pollTimer); pollTimer=setInterval(()=>pollBuild(activeBuildId),2500); pollBuild(activeBuildId);
      loadHistory();
    }catch(error){showStatus('Could not start build',error.message,0,true);buildButton.disabled=false;buildButton.textContent='Try Again';}
  });
  form.addEventListener('reset',()=>{setTimeout(()=>{setMode('quick');statusBox.classList.remove('show');document.getElementById('ak-icon-preview').textContent='K';document.getElementById('ak-preview-icon').textContent='K';document.getElementById('ak-preview-name').textContent='Your App Name';document.getElementById('ak-preview-url').textContent='yourwebsite.com';},0);});
  async function loadHistory(){
    if(!apiReady) return;
    const body=document.getElementById('ak-history-body');
    try{
      const data=await parseResponse(await fetch(API_BASE+'/api/builds?limit=12'));
      body.replaceChildren();
      if(!data.builds.length){const tr=document.createElement('tr');const td=document.createElement('td');td.colSpan=5;td.className='ak-empty';td.textContent='No builds yet. Your builds will appear here.';tr.appendChild(td);body.appendChild(tr);return;}
      data.builds.forEach(item=>{
        const tr=document.createElement('tr');
        const values=[item.app_name,item.mode,item.build_type.toUpperCase()];
        values.forEach(v=>{const td=document.createElement('td');td.textContent=v;tr.appendChild(td);});
        const state=document.createElement('td');const badge=document.createElement('span');badge.className='ak-badge '+(item.status==='completed'?'done':item.status==='failed'?'failed':'');badge.textContent=item.status;state.appendChild(badge);tr.appendChild(state);
        const action=document.createElement('td');if(item.status==='completed'){const a=document.createElement('a');a.className='ak-small-link';a.href=API_BASE+'/api/builds/'+encodeURIComponent(item.id)+'/download';a.textContent='Download';action.appendChild(a);}else{action.textContent='—';}tr.appendChild(action);body.appendChild(tr);
      });
    }catch(error){body.innerHTML='<tr><td class="ak-empty" colspan="5">Could not load build history. Check the backend URL.</td></tr>';}
  }
  document.getElementById('ak-refresh-history').addEventListener('click',loadHistory);
  loadHistory();
})();
